    56  // The function getPathFromState that we are using in some places isn't working correctly without defined index.
    57  const getRoutesWithIndex = (routes: NavigationPartialRoute[]): PartialState<NavigationState> => ({routes, index: routes.length - 1});
    58
    59  const addPolicyIDToRoute = (route: NavigationPartialRoute, policyID?: string) => {
    60      const routeWithPolicyID = {...route};
    61      if (!routeWithPolicyID.params) {
    62          routeWithPolicyID.params = {policyID};
    63          return routeWithPolicyID;
    64      }
    65
    66      if ('policyID' in routeWithPolicyID.params && !!routeWithPolicyID.params.policyID) {
    67          return routeWithPolicyID;
    68      }
    69
    70      routeWithPolicyID.params = {...routeWithPolicyID.params, policyID};
    71
    72      return routeWithPolicyID;
    73  };
