    75  function createBottomTabNavigator(route: NavigationPartialRoute<BottomTabName>, policyID?: string): NavigationPartialRoute<typeof NAVIGATORS.BOTTOM_TAB_NAVIGATOR> {
    76      const routesForBottomTabNavigator: Array<NavigationPartialRoute<BottomTabName>> = [];
    77      routesForBottomTabNavigator.push(addPolicyIDToRoute(route, policyID) as NavigationPartialRoute<BottomTabName>);
    78
    79      return {
    80          name: NAVIGATORS.BOTTOM_TAB_NAVIGATOR,
    81          state: getRoutesWithIndex(routesForBottomTabNavigator),
    82      };
    83  }
