    85  function createFullScreenNavigator(route?: NavigationPartialRoute<FullScreenName>): NavigationPartialRoute<typeof NAVIGATORS.FULL_SCREEN_NAVIGATOR> {
    86      const routes = [];
    87
    88      const policyID = route?.params && 'policyID' in route.params ? route.params.policyID : undefined;
    89
    90      // Both routes in FullScreenNavigator should store a policyID in params, so here this param is also passed to the screen displayed in LHN in FullScreenNavigator
    91      routes.push({
    92          name: SCREENS.WORKSPACE.INITIAL,
    93          params: {
    94              policyID,
    95          },
    96      });
    97
    98      if (route) {
    99          routes.push(route);
   100      }
   101      return {
   102          name: NAVIGATORS.FULL_SCREEN_NAVIGATOR,
   103          state: getRoutesWithIndex(routes),
   104      };
   105  }
