   107  function getParamsFromRoute(screenName: string): string[] {
   108      const routeConfig = normalizedConfigs[screenName as Screen];
   109
   110      const route = routeConfig.pattern;
   111
   112      return route.match(/(?<=[:?&])(\w+)(?=[/=?&]|$)/g) ?? [];
   113  }
