   115  // This function will return CentralPaneNavigator route or FullScreenNavigator route.
   116  function getMatchingRootRouteForRHPRoute(route: NavigationPartialRoute): NavigationPartialRoute<CentralPaneName | typeof NAVIGATORS.FULL_SCREEN_NAVIGATOR> | undefined {
   117      // Check for backTo param. One screen with different backTo value may need diferent screens visible under the overlay.
   118      if (route.params && 'backTo' in route.params && typeof route.params.backTo === 'string') {
   119          const stateForBackTo = getStateFromPath(route.params.backTo, config);
   120          if (stateForBackTo) {
   121              // If there is rhpNavigator in the state generated for backTo url, we want to get root route matching to this rhp screen.
   122              const rhpNavigator = stateForBackTo.routes.find((rt) => rt.name === NAVIGATORS.RIGHT_MODAL_NAVIGATOR);
   123              if (rhpNavigator && rhpNavigator.state) {
   124                  return getMatchingRootRouteForRHPRoute(findFocusedRoute(stateForBackTo) as NavigationPartialRoute);
   125              }
   126
   127              // If we know that backTo targets the root route (full screen) we want to use it.
   128              const fullScreenNavigator = stateForBackTo.routes.find((rt) => rt.name === NAVIGATORS.FULL_SCREEN_NAVIGATOR);
   129              if (fullScreenNavigator && fullScreenNavigator.state) {
   130                  return fullScreenNavigator as NavigationPartialRoute<CentralPaneName | typeof NAVIGATORS.FULL_SCREEN_NAVIGATOR>;
   131              }
   132
   133              // If we know that backTo targets a central pane screen we want to use it.
   134              const centralPaneScreen = stateForBackTo.routes.find((rt) => isCentralPaneName(rt.name));
   135              if (centralPaneScreen) {
   136                  return centralPaneScreen as NavigationPartialRoute<CentralPaneName | typeof NAVIGATORS.FULL_SCREEN_NAVIGATOR>;
   137              }
   138          }
   139      }
   140
   141      // Check for CentralPaneNavigator
   142      for (const [centralPaneName, RHPNames] of Object.entries(CENTRAL_PANE_TO_RHP_MAPPING)) {
   143          if (RHPNames.includes(route.name)) {
   144              const paramsFromRoute = getParamsFromRoute(centralPaneName);
   145
   146              return {name: centralPaneName as CentralPaneName, params: pick(route.params, paramsFromRoute)};
   147          }
   148      }
   149
   150      // Check for FullScreenNavigator
   151      for (const [fullScreenName, RHPNames] of Object.entries(FULL_SCREEN_TO_RHP_MAPPING)) {
   152          if (RHPNames.includes(route.name)) {
   153              const paramsFromRoute = getParamsFromRoute(fullScreenName);
   154
   155              return createFullScreenNavigator({name: fullScreenName as FullScreenName, params: pick(route.params, paramsFromRoute)});
   156          }
   157      }
   158
   159      // check for valid reportID in the route params
   160      // if the reportID is valid, we should navigate back to screen report in CPN
   161      const reportID = (route.params as Record<string, string | undefined>)?.reportID;
   162      if (ReportConnection.getAllReports()?.[`${ONYXKEYS.COLLECTION.REPORT}${reportID}`]?.reportID) {
   163          return {name: SCREENS.REPORT, params: {reportID}};
   164      }
   165  }
