   167  function getAdaptedState(state: PartialState<NavigationState<RootStackParamList>>, policyID?: string): GetAdaptedStateReturnType {
   168      const isNarrowLayout = getIsNarrowLayout();
   169      const metainfo = {
   170          isCentralPaneAndBottomTabMandatory: true,
   171          isFullScreenNavigatorMandatory: true,
   172      };
   173
   174      // We need to check what is defined to know what we need to add.
   175      const bottomTabNavigator = state.routes.find((route) => route.name === NAVIGATORS.BOTTOM_TAB_NAVIGATOR);
   176      const centralPaneNavigator = state.routes.find((route) => isCentralPaneName(route.name));
   177      const fullScreenNavigator = state.routes.find((route) => route.name === NAVIGATORS.FULL_SCREEN_NAVIGATOR);
   178      const rhpNavigator = state.routes.find((route) => route.name === NAVIGATORS.RIGHT_MODAL_NAVIGATOR);
   179      const lhpNavigator = state.routes.find((route) => route.name === NAVIGATORS.LEFT_MODAL_NAVIGATOR);
   180      const onboardingModalNavigator = state.routes.find((route) => route.name === NAVIGATORS.ONBOARDING_MODAL_NAVIGATOR);
   181      const welcomeVideoModalNavigator = state.routes.find((route) => route.name === NAVIGATORS.WELCOME_VIDEO_MODAL_NAVIGATOR);
   182      const attachmentsScreen = state.routes.find((route) => route.name === SCREENS.ATTACHMENTS);
   183      const featureTrainingModalNavigator = state.routes.find((route) => route.name === NAVIGATORS.FEATURE_TRANING_MODAL_NAVIGATOR);
   184
   185      if (rhpNavigator) {
   186          // Routes
   187          // - matching bottom tab
   188          // - matching root route for rhp
   189          // - found rhp
   190
   191          // This one will be defined because rhpNavigator is defined.
   192          const focusedRHPRoute = findFocusedRoute(state);
   193          const routes = [];
   194
   195          if (focusedRHPRoute) {
   196              let matchingRootRoute = getMatchingRootRouteForRHPRoute(focusedRHPRoute);
   197              const isRHPScreenOpenedFromLHN = focusedRHPRoute?.name && RHP_SCREENS_OPENED_FROM_LHN.includes(focusedRHPRoute?.name as RHPScreenOpenedFromLHN);
   198              // This may happen if this RHP doesn't have a route that should be under the overlay defined.
   199              if (!matchingRootRoute || isRHPScreenOpenedFromLHN) {
   200                  metainfo.isCentralPaneAndBottomTabMandatory = false;
   201                  metainfo.isFullScreenNavigatorMandatory = false;
   202                  // If matchingRootRoute is undefined and it's a narrow layout, don't add a report screen under the RHP.
   203                  matchingRootRoute = matchingRootRoute ?? (!isNarrowLayout ? {name: SCREENS.REPORT} : undefined);
   204              }
   205
   206              // If the root route is type of FullScreenNavigator, the default bottom tab will be added.
   207              const matchingBottomTabRoute = getMatchingBottomTabRouteForState({routes: matchingRootRoute ? [matchingRootRoute] : []});
   208              routes.push(createBottomTabNavigator(matchingBottomTabRoute, policyID));
   209              // When we open a screen in RHP from FullScreenNavigator, we need to add the appropriate screen in CentralPane.
   210              // Then, when we close FullScreenNavigator, we will be redirected to the correct page in CentralPane.
   211              if (matchingRootRoute?.name === NAVIGATORS.FULL_SCREEN_NAVIGATOR) {
   212                  routes.push({name: SCREENS.SETTINGS.WORKSPACES});
   213              }
   214
   215              if (matchingRootRoute && (!isNarrowLayout || !isRHPScreenOpenedFromLHN)) {
   216                  routes.push(matchingRootRoute);
   217              }
   218          }
   219
   220          routes.push(rhpNavigator);
   221          return {
   222              adaptedState: getRoutesWithIndex(routes),
   223              metainfo,
   224          };
   225      }
   226      if (lhpNavigator ?? onboardingModalNavigator ?? welcomeVideoModalNavigator ?? featureTrainingModalNavigator) {
   227          // Routes
   228          // - default bottom tab
   229          // - default central pane on desktop layout
   230          // - found lhp / onboardingModalNavigator
   231
   232          // There is no screen in these navigators that would have mandatory central pane, bottom tab or fullscreen navigator.
   233          metainfo.isCentralPaneAndBottomTabMandatory = false;
   234          metainfo.isFullScreenNavigatorMandatory = false;
   235          const routes = [];
   236          routes.push(
   237              createBottomTabNavigator(
   238                  {
   239                      name: SCREENS.HOME,
   240                  },
   241                  policyID,
   242              ),
   243          );
   244          if (!isNarrowLayout) {
   245              routes.push({
   246                  name: SCREENS.REPORT,
   247              });
   248          }
   249
   250          // Separate ifs are necessary for typescript to see that we are not pushing undefined to the array.
   251          if (lhpNavigator) {
   252              routes.push(lhpNavigator);
   253          }
   254
   255          if (onboardingModalNavigator) {
   256              routes.push(onboardingModalNavigator);
   257          }
   258
   259          if (welcomeVideoModalNavigator) {
   260              routes.push(welcomeVideoModalNavigator);
   261          }
   262
   263          if (featureTrainingModalNavigator) {
   264              routes.push(featureTrainingModalNavigator);
   265          }
   266
   267          return {
   268              adaptedState: getRoutesWithIndex(routes),
   269              metainfo,
   270          };
   271      }
   272      if (fullScreenNavigator) {
   273          // Routes
   274          // - default bottom tab
   275          // - default central pane on desktop layout
   276          // - found fullscreen
   277
   278          const routes = [];
   279          routes.push(
   280              createBottomTabNavigator(
   281                  {
   282                      name: SCREENS.SETTINGS.ROOT,
   283                  },
   284                  policyID,
   285              ),
   286          );
   287
   288          routes.push({
   289              name: SCREENS.SETTINGS.WORKSPACES,
   290          });
   291
   292          routes.push(fullScreenNavigator);
   293
   294          return {
   295              adaptedState: getRoutesWithIndex(routes),
   296              metainfo,
   297          };
   298      }
   299      if (centralPaneNavigator) {
   300          // Routes
   301          // - matching bottom tab
   302          // - found central pane
   303          const routes = [];
   304          const matchingBottomTabRoute = getMatchingBottomTabRouteForState(state);
   305          routes.push(createBottomTabNavigator(matchingBottomTabRoute, policyID));
   306          routes.push(centralPaneNavigator);
   307
   308          return {
   309              adaptedState: getRoutesWithIndex(routes),
   310              metainfo,
   311          };
   312      }
   313      if (attachmentsScreen) {
   314          // Routes
   315          // - matching bottom tab
   316          // - central pane (report screen) of the attachment
   317          // - found report attachments
   318          const routes = [];
   319          const reportAttachments = attachmentsScreen as Route<'Attachments', RootStackParamList['Attachments']>;
   320
   321          if (reportAttachments.params?.type === CONST.ATTACHMENT_TYPE.REPORT) {
   322              const matchingBottomTabRoute = getMatchingBottomTabRouteForState(state);
   323              routes.push(createBottomTabNavigator(matchingBottomTabRoute, policyID));
   324              if (!isNarrowLayout) {
   325                  routes.push({name: SCREENS.REPORT, params: {reportID: reportAttachments.params?.reportID ?? '-1'}});
   326              }
   327              routes.push(reportAttachments);
   328
   329              return {
   330                  adaptedState: getRoutesWithIndex(routes),
   331                  metainfo,
   332              };
   333          }
   334      }
   335
   336      // We need to make sure that this if only handles states where we deeplink to the bottom tab directly
   337      if (bottomTabNavigator && bottomTabNavigator.state) {
   338          // Routes
   339          // - found bottom tab
   340          // - matching central pane on desktop layout
   341
   342          // We want to make sure that the bottom tab search page is always pushed with matching central pane page. Even on the narrow layout.
   343          if (isNarrowLayout && bottomTabNavigator.state?.routes.at(0)?.name !== SCREENS.SEARCH.BOTTOM_TAB) {
   344              return {
   345                  adaptedState: state,
   346                  metainfo,
   347              };
   348          }
   349
   350          const routes = [...state.routes];
   351          const matchingCentralPaneRoute = getMatchingCentralPaneRouteForState(state);
   352          if (matchingCentralPaneRoute) {
   353              routes.push(matchingCentralPaneRoute);
   354          } else {
   355              // If there is no matching central pane, we want to add the default one.
   356              metainfo.isCentralPaneAndBottomTabMandatory = false;
   357              routes.push({name: SCREENS.REPORT});
   358          }
   359
   360          return {
   361              adaptedState: getRoutesWithIndex(routes),
   362              metainfo,
   363          };
   364      }
   365
   366      return {
   367          adaptedState: state,
   368          metainfo,
   369      };
   370  }
