   372  const getAdaptedStateFromPath: GetAdaptedStateFromPath = (path, options, shouldReplacePathInNestedState = true) => {
   373      const normalizedPath = !path.startsWith('/') ? `/${path}` : path;
   374      const pathWithoutPolicyID = getPathWithoutPolicyID(normalizedPath);
   375      const isAnonymous = isAnonymousUser();
   376
   377      // Anonymous users don't have access to workspaces
   378      const policyID = isAnonymous ? undefined : extractPolicyIDFromPath(path);
   379
   380      const state = getStateFromPath(pathWithoutPolicyID, options) as PartialState<NavigationState<RootStackParamList>>;
   381      if (shouldReplacePathInNestedState) {
   382          replacePathInNestedState(state, normalizedPath);
   383      }
   384      if (state === undefined) {
   385          throw new Error('Unable to parse path');
   386      }
   387
   388      // On SCREENS.SEARCH.CENTRAL_PANE policyID is stored differently inside search query ("q" param), so we're handling this case
   389      const focusedRoute = findFocusedRoute(state);
   390      const policyIDFromQuery = extractPolicyIDFromQuery(focusedRoute);
   391
   392      return getAdaptedState(state, policyID ?? policyIDFromQuery);
   393  };
